// Exact ULC Linz Oberbank PWA artwork, byte-for-byte from old ULC application.
// Original PNG files preserved in ../assets/pwa for provenance and verification.
export const ULC_PWA_MANIFEST = {
  id: "/",
  name: "ULC Linz Oberbank",
  short_name: "ULC Linz",
  description: "Vereins-App des ULC Linz Oberbank für Training, Planung, Dokumentation und Verwaltung.",
  start_url: "/",
  scope: "/",
  display: "standalone",
  background_color: "#f4f8f5",
  theme_color: "#147a46",
  lang: "de-AT",
  icons: [
    { src: "/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
    { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
    { src: "/icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
  ],
};
export const ULC_PWA_SERVICE_WORKER = `
self.addEventListener("install", () => self.skipWaiting());
self.addEventListener("activate", (event) => event.waitUntil(self.clients.claim()));
self.addEventListener("fetch", (event) => {
  if (event.request.method !== "GET" ||
      new URL(event.request.url).origin !== self.location.origin) return;
  // Network-only. Never cache private API data, authenticated pages or sessions.
  event.respondWith(fetch(event.request));
});
`;
const ICON_192 = "";
const ICON_512 = "";
const ICON_MASKABLE_512 = "";
const ICON_APPLE_TOUCH = "";
const CLUB_LOGO = "";
function decodePng(value: string): Uint8Array<ArrayBuffer> {
  const decoded = atob(value);
  const bytes = new Uint8Array(new ArrayBuffer(decoded.length));
  for (let i = 0; i < decoded.length; i += 1) bytes[i] = decoded.charCodeAt(i);
  return bytes;
}
export function generatedPwaResponse(request: Request): Response | null {
  if (request.method !== "GET" && request.method !== "HEAD") return null;
  const path = new URL(request.url).pathname;
  let body: string | Uint8Array<ArrayBuffer>;
  let type: string;
  switch (path) {
    case "/manifest.webmanifest": body = JSON.stringify(ULC_PWA_MANIFEST); type = "application/manifest+json; charset=utf-8"; break;
    case "/sw.js": body = ULC_PWA_SERVICE_WORKER; type = "text/javascript; charset=utf-8"; break;
    case "/icon-192.png": body = decodePng(ICON_192); type = "image/png"; break;
    case "/icon-512.png": body = decodePng(ICON_512); type = "image/png"; break;
    case "/icon-maskable-512.png": body = decodePng(ICON_MASKABLE_512); type = "image/png"; break;
    case "/apple-touch-icon.png": body = decodePng(ICON_APPLE_TOUCH); type = "image/png"; break;
    case "/logo.png": body = decodePng(CLUB_LOGO); type = "image/png"; break;
    default: return null;
  }
  return new Response(request.method === "HEAD" ? null : body, {
    status: 200,
    headers: {
      "content-type": type,
      "cache-control": path === "/sw.js" || path === "/manifest.webmanifest" ? "no-store" : "public, max-age=3600",
      "x-content-type-options": "nosniff",
      ...(path === "/sw.js" ? { "service-worker-allowed": "/" } : {}),
    },
  });
}
